  return <PublicShell><PageIntro kicker="Selected work" title={<>Good work leaves a <span className="text-gradient">trace.</span></>} body="Case notes from teams who chose to make a meaningful change—and gave us a seat at the table." /><main className="mx-auto max-w-7xl px-5 pb-24 lg:px-8"><div className="grid gap-3 border-y border-slate-200 py-5 dark:border-slate-800 md:grid-cols-2"><label className="relative"><Search className="absolute left-3 top-3 text-slate-400" size={17} /><input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search case notes..." className="h-11 w-full rounded-lg border border-slate-200 bg-white pl-10 pr-4 text-sm outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-900" data-testid="input-project-search" /></label><div className="flex gap-2 overflow-x-auto">{industries.map((item) => <button key={item} onClick={() => setIndustry(item)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-xs font-bold ${industry === item ? 'bg-slate-950 text-white' : 'bg-slate-100 text-slate-500 dark:bg-slate-800'}`} data-testid={`filter-project-industry-${item}`}>{item}</button>)}</div><select value={technology} onChange={(e) => setTechnology(e.target.value)} className="h-11 rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold outline-none dark:border-slate-700 dark:bg-slate-900" data-testid="select-project-technology">{technologies.map((item) => <option key={item}>{item}</option>)}</select><select value={service} onChange={(e) => setService(e.target.value)} className="h-11 rounded-lg border border-slate-200 bg-white px-3 text-sm font-bold outline-none dark:border-slate-700 dark:bg-slate-900" data-testid="select-project-service">{services.map((item) => <option key={item}>{item}</option>)}</select></div><div className="mt-10 grid gap-6">{visible.map((project, i) => <Link href={`/projects/${project.slug}`} key={project.id} className={`group grid gap-0 overflow-hidden rounded-2xl border border-slate-200 bg-white dark:border-slate-800 dark:bg-slate-900 ${i % 2 ? '' : ''} md:grid-cols-2`} data-testid={`card-project-${project.id}`}><AbstractVisual variant={project.image === 'clinical' ? 'care' : project.image === 'lumen' ? 'energy' : 'finance'} className="min-h-[280px] rounded-none md:min-h-[340px]" /><div className="flex flex-col justify-center p-8 lg:p-12"><span className="font-mono text-[10px] uppercase tracking-[.2em] text-cyan-600">{project.industry}</span><h2 className="mt-5 text-3xl font-black tracking-[-.05em]">{project.title}</h2><p className="mt-4 max-w-md leading-7 text-slate-500">{project.description}</p><div className="mt-8 flex flex-wrap gap-2">{project.technologies.map((t) => <span key={t} className="rounded-md bg-slate-100 px-2 py-1 font-mono text-[9px] text-slate-500 dark:bg-slate-800">{t}</span>)}</div><span className="mt-10 flex items-center gap-2 text-sm font-bold text-blue-600">Read case note <ArrowRight size={15} className="transition-transform group-hover:translate-x-1" /></span></div></Link>)}</div>{visible.length === 0 && <Empty text="No case notes match those filters." />}</main></PublicShell>;
