function Appointment() {
  const { data, update } = useStore(); const params = new URLSearchParams(window.location.search); const initial = data.services.find((s) => s.slug === params.get('service'))?.name || ''; const [form, setForm] = useState({ firstName: '', lastName: '', email: '', phone: '', preferredDate: '', message: initial ? `I'm interested in exploring ${initial}.` : '' }); const [sent, setSent] = useState(false); const [error, setError] = useState('');
  const change = (key: string, value: string) => setForm((f) => ({ ...f, [key]: value }));
  const submit = (e: FormEvent) => { e.preventDefault(); if (!form.firstName || !form.lastName || !form.email || !form.message || !form.preferredDate) { setError('Please complete the required fields so we can prepare well.'); return; } if (!/^\S+@\S+\.\S+$/.test(form.email)) { setError('Please enter a valid email address.'); return; } const recentDuplicate = data.leads.some((lead) => lead.email.toLowerCase() === form.email.toLowerCase() && Date.now() - new Date(lead.submittedAt).getTime() < 86400000); if (recentDuplicate) { setError('We already have a request from this email in the last 24 hours.'); return; } update('leads', [...data.leads, { ...form, id: `l${Date.now()}`, status: 'new', submittedAt: new Date().toISOString() }]); setSent(true); setError(''); };
  if (sent) return <PublicShell><main className="mx-auto min-h-[600px] max-w-3xl px-5 py-24 text-center"><span className="mx-auto grid h-16 w-16 place-items-center rounded-full bg-cyan-400 text-slate-950"><Check size={28} /></span><Kicker>Message received</Kicker><h1 className="mt-5 text-5xl font-black tracking-[-.06em]">We’ll bring the good questions.</h1><p className="mx-auto mt-5 max-w-lg text-lg leading-8 text-slate-500">Thanks, {form.firstName}. A member of our team will be in touch within one business day.</p><Link href="/" className="mt-9 inline-flex items-center gap-2 text-sm font-bold text-blue-600" data-testid="appointment-home">Back to home <ArrowRight size={15} /></Link></main></PublicShell>;
  return <PublicShell><main className="hero-grid min-h-[720px] border-b border-slate-200 py-20 dark:border-slate-800"><div className="mx-auto grid max-w-7xl gap-14 px-5 lg:grid-cols-[.8fr_1.2fr] lg:px-8"><div><Kicker>Start a conversation</Kicker><h1 className="mt-6 text-5xl font-black tracking-[-.065em] text-slate-950 dark:text-white sm:text-7xl">Let’s make the next move <span className="text-gradient">useful.</span></h1><p className="mt-7 max-w-md text-lg leading-8 text-slate-500">Tell us where you are, what’s getting in the way, and what better could look like. We’ll come prepared.</p><div className="mt-12 space-y-5 text-sm text-slate-600 dark:text-slate-400"><p className="flex items-center gap-3"><CalendarDays size={17} className="text-cyan-500" /> 45-minute working session</p><p className="flex items-center gap-3"><Users size={17} className="text-cyan-500" /> Senior practitioners, not a sales relay</p><p className="flex items-center gap-3"><CircleHelp size={17} className="text-cyan-500" /> No obligation, just clarity</p></div></div><form onSubmit={submit} className="surface rounded-2xl p-6 sm:p-9"><div className="grid gap-5 sm:grid-cols-2">{[['firstName','First name','Mira'],['lastName','Last name','Patel'],['email','Work email','you@company.com'],['phone','Phone (optional)','+1 555 000 0000']].map(([key,label,placeholder]) => <label className="grid gap-2 text-xs font-bold text-slate-700 dark:text-slate-300" key={key}>{label}<input value={form[key as keyof typeof form]} onChange={(e) => change(key, e.target.value)} placeholder={placeholder} type={key === 'email' ? 'email' : 'text'} className="h-11 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-normal outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-800" data-testid={`input-appointment-${key}`} /></label>)}</div><label className="mt-5 grid gap-2 text-xs font-bold text-slate-700 dark:text-slate-300">Preferred date<input value={form.preferredDate} onChange={(e) => change('preferredDate', e.target.value)} type="date" className="h-11 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-normal outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-800" data-testid="input-appointment-date" /></label><label className="mt-5 grid gap-2 text-xs font-bold text-slate-700 dark:text-slate-300">What are you working through?<textarea value={form.message} onChange={(e) => change('message', e.target.value)} rows={5} placeholder="A little context helps us bring the right people." className="resize-none rounded-lg border border-slate-200 bg-slate-50 p-3 text-sm font-normal outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-800" data-testid="input-appointment-message" /></label>{error && <p className="mt-4 rounded-lg bg-red-50 p-3 text-xs font-bold text-red-600" data-testid="status-appointment-error">{error}</p>}<Button type="submit" className="mt-6 w-full py-3.5" data-testid="button-submit-appointment">Request a working session <ArrowRight size={15} /></Button><p className="mt-4 text-center text-[11px] text-slate-400">We respect your inbox. Your details stay between us.</p></form></div></main></PublicShell>;
}

function Empty({ text }: { text: string }) { return <div className="mx-auto max-w-7xl px-5 py-24 text-center"><div className="mx-auto grid h-14 w-14 place-items-center rounded-xl bg-cyan-50 text-cyan-600"><Search size={22} /></div><p className="mt-5 font-bold text-slate-500">{text}</p></div>; }

function AdminLogin() {
  const [, setLocation] = useLocation(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); if (email === 'admin@example.com' && password === 'password123') { localStorage.setItem('antitude-admin', 'true'); setLocation('/admin'); } else setError('Use admin@example.com and password123 for the demo workspace.'); };
  return <div className="hero-grid flex min-h-[100dvh] items-center justify-center px-5 py-12"><div className="w-full max-w-md"><Logo /><div className="surface mt-10 rounded-2xl p-7 sm:p-9"><div className="grid h-12 w-12 place-items-center rounded-xl bg-slate-950 text-cyan-400"><LockKeyhole size={20} /></div><h1 className="mt-7 text-3xl font-black tracking-[-.05em]">Workspace access</h1><p className="mt-2 text-sm text-slate-500">A private view of your Antitude content and conversations.</p><form onSubmit={submit} className="mt-8 grid gap-4"><label className="grid gap-2 text-xs font-bold">Email<input value={email} onChange={(e) => setEmail(e.target.value)} type="email" placeholder="admin@example.com" className="h-11 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-normal outline-none focus:border-cyan-400" data-testid="input-admin-email" /></label><label className="grid gap-2 text-xs font-bold">Password<input value={password} onChange={(e) => setPassword(e.target.value)} type="password" placeholder="password123" className="h-11 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-normal outline-none focus:border-cyan-400" data-testid="input-admin-password" /></label>{error && <p className="rounded-lg bg-red-50 p-3 text-xs font-bold text-red-600" data-testid="status-admin-error">{error}</p>}<Button type="submit" className="mt-2 w-full" data-testid="button-admin-login">Enter workspace <ArrowRight size={15} /></Button></form></div><Link href="/" className="mt-6 block text-center text-xs font-bold text-slate-500 hover:text-slate-950" data-testid="link-admin-back">Back to public site</Link></div></div>;
}

const adminNav = [['Overview', '/admin', LayoutDashboard], ['Services', '/admin/services', BriefcaseBusiness], ['Technologies', '/admin/technologies', Zap], ['Solutions', '/admin/solutions', Globe2], ['Projects', '/admin/projects', FileText], ['Leads', '/admin/leads', Users]] as const;
function AdminShell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation(); const [open, setOpen] = useState(false); const authed = localStorage.getItem('antitude-admin') === 'true';
  if (!authed) { setTimeout(() => setLocation('/admin/login'), 0); return null; }
  return <div className="min-h-[100dvh] bg-slate-100 dark:bg-slate-950"><aside className={`fixed inset-y-0 left-0 z-50 w-64 transform bg-slate-950 px-4 py-5 text-white transition-transform lg:translate-x-0 ${open ? 'translate-x-0' : '-translate-x-full'}`}><div className="flex items-center justify-between px-2"><Logo light /><button onClick={() => setOpen(false)} className="lg:hidden" data-testid="button-close-admin-nav"><X size={18} /></button></div><p className="mt-12 px-3 font-mono text-[9px] uppercase tracking-[.2em] text-slate-600">Workspace</p><nav className="mt-3 grid gap-1">{adminNav.map(([label, href, Icon]) => <Link href={href} onClick={() => setOpen(false)} key={href} className={`flex items-center gap-3 rounded-lg px-3 py-3 text-sm font-bold ${location === href ? 'bg-cyan-400 text-slate-950' : 'text-slate-400 hover:bg-slate-900 hover:text-white'}`} data-testid={`admin-nav-${label.toLowerCase()}`}><Icon size={17} />{label}</Link>)}</nav><div className="absolute bottom-5 left-4 right-4 border-t border-slate-800 pt-4"><button onClick={() => { localStorage.removeItem('antitude-admin'); setLocation('/admin/login'); }} className="flex w-full items-center gap-3 rounded-lg px-3 py-3 text-sm font-bold text-slate-500 hover:bg-slate-900 hover:text-white" data-testid="button-admin-logout"><LogOut size={17} />Sign out</button></div></aside><div className="lg:pl-64"><header className="sticky top-0 z-30 flex h-[72px] items-center justify-between border-b border-slate-200 bg-white/90 px-5 backdrop-blur-xl dark:border-slate-800 dark:bg-slate-900/90 lg:px-8"><button onClick={() => setOpen(true)} className="rounded-lg border border-slate-200 p-2 lg:hidden" data-testid="button-open-admin-nav"><Menu size={18} /></button><div className="hidden items-center gap-2 text-xs text-slate-400 sm:flex"><span className="grid h-7 w-7 place-items-center rounded-md bg-cyan-50 text-cyan-600"><ShieldCheck size={15} /></span> Local workspace <span className="text-slate-300">/</span> Synced to browser</div><div className="ml-auto flex items-center gap-2"><ThemeToggle /><span className="grid h-8 w-8 place-items-center rounded-full bg-slate-950 font-mono text-[10px] font-bold text-cyan-400">AD</span></div></header><main className="mx-auto max-w-7xl px-5 py-8 lg:px-8">{children}</main></div></div>;
}

function AdminDashboard() {
  const { data } = useStore(); const newLeads = data.leads.filter((l) => l.status === 'new').length;
  const stats: Array<{ label: string; value: number; Icon: ComponentType<{ size?: number; className?: string }>; detail: string }> = [
    { label: 'Published services', value: data.services.length, Icon: BriefcaseBusiness, detail: 'All capabilities' },
    { label: 'Technologies', value: data.technologies.length, Icon: Zap, detail: 'In the toolkit' },
    { label: 'Case studies', value: data.projects.length, Icon: FileText, detail: 'Selected work' },
    { label: 'New leads', value: newLeads, Icon: TrendingUp, detail: 'Needs attention' },
  ];
  return <AdminShell><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><Kicker>Monday, September 14, 2026</Kicker><h1 className="mt-3 text-3xl font-black tracking-[-.05em]">Good morning, Admin.</h1><p className="mt-2 text-sm text-slate-500">Here’s the shape of Antitude today.</p></div><Link href="/appointment" className="inline-flex items-center gap-2 self-start rounded-lg bg-cyan-400 px-4 py-2.5 text-xs font-black text-slate-950" data-testid="admin-view-site">View public site <ExternalLink size={14} /></Link></div><div className="mt-8 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{stats.map(({ label, value, Icon, detail }) => <div key={label} className="surface rounded-xl p-5"><div className="flex items-center justify-between"><span className="text-xs font-bold text-slate-500">{label}</span><Icon size={17} className="text-cyan-500" /></div><p className="mt-5 text-4xl font-black tracking-[-.06em]">{value}</p><p className="mt-2 text-xs text-slate-400">{detail}</p></div>)}</div><div className="mt-8 grid gap-5 lg:grid-cols-[1.2fr_.8fr]"><div className="surface rounded-xl p-6"><div className="flex items-center justify-between"><div><p className="font-mono text-[10px] font-bold uppercase tracking-[.18em] text-cyan-600">Lead pipeline</p><h2 className="mt-2 text-lg font-black">Recent conversations</h2></div><Link href="/admin/leads" className="text-xs font-bold text-blue-600" data-testid="dashboard-leads-link">View all</Link></div><div className="mt-6 grid gap-2">{data.leads.slice(0, 4).map((lead) => <Link href="/admin/leads" key={lead.id} className="flex items-center justify-between rounded-lg bg-slate-50 p-3 dark:bg-slate-800" data-testid={`dashboard-lead-${lead.id}`}><div><p className="text-sm font-bold">{lead.firstName} {lead.lastName}</p><p className="mt-1 text-xs text-slate-500">{lead.email}</p></div><Status status={lead.status} /></Link>)}</div></div><div className="rounded-xl bg-slate-950 p-6 text-white"><p className="font-mono text-[10px] font-bold uppercase tracking-[.18em] text-cyan-400">Workspace health</p><h2 className="mt-2 text-lg font-black">Everything is local.</h2><p className="mt-4 text-sm leading-6 text-slate-400">Your seeded content and lead updates persist in this browser. Reset or export anytime from the Leads workspace.</p><div className="mt-8 flex items-center gap-3 text-xs font-bold text-cyan-400"><span className="h-2 w-2 rounded-full bg-cyan-400" /> All systems nominal</div></div></div></AdminShell>;
}

function Status({ status }: { status: string }) { const colors: Record<string, string> = { new: 'bg-cyan-100 text-cyan-700', contacted: 'bg-amber-100 text-amber-700', qualified: 'bg-blue-100 text-blue-700', lost: 'bg-slate-200 text-slate-600' }; return <span className={`rounded-full px-2.5 py-1 font-mono text-[9px] font-bold uppercase ${colors[status] || colors.new}`} data-testid={`status-${status}`}>{status}</span>; }

type ResourceKey = 'services' | 'technologies' | 'solutions' | 'projects';
function AdminResource({ kind }: { kind: ResourceKey }) {
  const { data, update } = useStore(); const [query, setQuery] = useState(''); const [editing, setEditing] = useState<any>(null);
  const titles = { services: 'Services', technologies: 'Technologies', solutions: 'Solutions', projects: 'Projects' }; const rows = data[kind] as any[]; const visible = rows.filter((r) => JSON.stringify(r).toLowerCase().includes(query.toLowerCase()));
  const blank = kind === 'services' ? { name: '', slug: '', description: '', detailedDescription: '', icon: 'spark', technologies: [] } : kind === 'technologies' ? { name: '', description: '', category: 'Artificial Intelligence', icon: 'spark' } : kind === 'solutions' ? { title: '', description: '', industry: 'Healthcare', image: 'care' } : { title: '', slug: '', description: '', fullDescription: '', technologies: [], services: [], image: 'clinical', industry: 'Healthcare', projectUrl: 'https://example.com' };
  const save = (e: FormEvent) => { e.preventDefault(); if (!editing) return; const item = { ...editing, id: editing.id || `${kind[0]}${Date.now()}`, slug: editing.slug || editing.name?.toLowerCase().replace(/[^a-z0-9]+/g, '-') || editing.title?.toLowerCase().replace(/[^a-z0-9]+/g, '-') }; update(kind, (editing.id ? rows.map((r) => r.id === editing.id ? item : r) : [...rows, item]) as any); setEditing(null); };
  const remove = (id: string) => { if (window.confirm('Delete this item?')) update(kind, rows.filter((r) => r.id !== id) as any); };
  return <AdminShell><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><Kicker>Content management</Kicker><h1 className="mt-3 text-3xl font-black tracking-[-.05em]">{titles[kind]}</h1><p className="mt-2 text-sm text-slate-500">{rows.length} records · changes save to this browser</p></div><Button onClick={() => setEditing(blank)} data-testid={`button-add-${kind}`}><Plus size={16} /> Add {kind.slice(0, -1)}</Button></div><div className="mt-8 flex items-center gap-3"><label className="relative max-w-sm flex-1"><Search className="absolute left-3 top-2.5 text-slate-400" size={16} /><input value={query} onChange={(e) => setQuery(e.target.value)} className="h-10 w-full rounded-lg border border-slate-200 bg-white pl-9 pr-3 text-sm outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-900" placeholder={`Search ${titles[kind].toLowerCase()}...`} data-testid={`input-admin-search-${kind}`} /></label><span className="rounded-lg bg-slate-200 px-3 py-2 font-mono text-[10px] text-slate-500 dark:bg-slate-800">{visible.length} shown</span></div>{editing && <form onSubmit={save} className="surface mt-5 rounded-xl p-5"><div className="mb-5 flex items-center justify-between"><h2 className="font-black">{editing.id ? 'Edit record' : 'New record'}</h2><button type="button" onClick={() => setEditing(null)} data-testid="button-close-editor"><X size={18} /></button></div><div className="grid gap-4 sm:grid-cols-2">{Object.entries(editing).filter(([key]) => key !== 'id').map(([key, value]) => <label key={key} className="grid gap-2 text-xs font-bold capitalize">{key}{Array.isArray(value) && <span className="font-normal text-slate-400">comma-separated</span>}<input value={Array.isArray(value) ? value.join(', ') : String(value ?? '')} onChange={(e) => setEditing({ ...editing, [key]: ['technologies', 'services'].includes(key) ? e.target.value.split(',').map((item) => item.trim()).filter(Boolean) : e.target.value })} className="h-10 rounded-lg border border-slate-200 bg-slate-50 px-3 text-sm font-normal outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-800" data-testid={`input-editor-${key}`} /></label>)}</div><div className="mt-5 flex justify-end gap-2"><Button type="button" variant="secondary" onClick={() => setEditing(null)} data-testid="button-cancel-editor">Cancel</Button><Button type="submit" data-testid="button-save-editor"><Check size={15} /> Save record</Button></div></form>}<div className="surface mt-5 overflow-hidden rounded-xl"><div className="divide-y divide-slate-200 dark:divide-slate-800">{visible.map((row) => <div className="flex items-center gap-4 p-4" key={row.id} data-testid={`admin-row-${row.id}`}><span className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-cyan-50 text-cyan-600 dark:bg-cyan-950">{icons[row.icon || 'spark']}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-black">{row.name || row.title}</p><p className="mt-1 truncate text-xs text-slate-500">{row.description}</p></div><span className="hidden rounded-full bg-slate-100 px-2.5 py-1 font-mono text-[9px] text-slate-500 sm:inline-block">{row.category || row.industry || (row.technologies || []).length + ' technologies'}</span><button onClick={() => setEditing(row)} className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-950" data-testid={`button-edit-${row.id}`}><Pencil size={16} /></button><button onClick={() => remove(row.id)} className="rounded-lg p-2 text-slate-400 hover:bg-red-50 hover:text-red-600" data-testid={`button-delete-${row.id}`}><Trash2 size={16} /></button></div>)}</div>{visible.length === 0 && <div className="p-10 text-center text-sm text-slate-500">No records found.</div>}</div></AdminShell>;
}

function AdminLeads() {
  const { data, update, reset } = useStore(); const [filter, setFilter] = useState('all'); const leads = data.leads.filter((l) => filter === 'all' || l.status === filter);
  const setStatus = (id: string, status: Lead['status']) => update('leads', data.leads.map((l) => l.id === id ? { ...l, status } : l)); const exportCsv = () => { const header = 'First name,Last name,Email,Phone,Preferred date,Status,Submitted at\\n'; const body = data.leads.map((l) => [l.firstName,l.lastName,l.email,l.phone,l.preferredDate,l.status,l.submittedAt].map((x) => `"${x.replaceAll('"','""')}"`).join(',')).join('\\n'); const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([header + body], { type: 'text/csv' })); a.download = 'antitude-leads.csv'; a.click(); URL.revokeObjectURL(a.href); };
  return <AdminShell><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><Kicker>Relationship desk</Kicker><h1 className="mt-3 text-3xl font-black tracking-[-.05em]">Leads</h1><p className="mt-2 text-sm text-slate-500">{data.leads.length} conversations in your local pipeline</p></div><div className="flex gap-2"><Button variant="secondary" onClick={exportCsv} data-testid="button-export-leads"><Download size={15} /> Export CSV</Button><Button variant="ghost" onClick={() => { if (window.confirm('Reset all content and leads to the seeded demo data?')) reset(); }} data-testid="button-reset-data">Reset data</Button></div></div><div className="mt-8 flex gap-2 overflow-x-auto">{['all','new','contacted','qualified','lost'].map((item) => <button key={item} onClick={() => setFilter(item)} className={`rounded-lg px-3 py-2 font-mono text-[10px] font-bold uppercase ${filter === item ? 'bg-slate-950 text-white' : 'bg-white text-slate-500 border border-slate-200'}`} data-testid={`filter-leads-${item}`}>{item} {item === 'all' ? data.leads.length : data.leads.filter((l) => l.status === item).length}</button>)}</div><div className="mt-5 grid gap-3">{leads.map((lead) => <div className="surface rounded-xl p-5" key={lead.id} data-testid={`lead-card-${lead.id}`}><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div className="flex items-start gap-3"><span className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-slate-950 font-mono text-xs font-bold text-cyan-400">{lead.firstName[0]}{lead.lastName[0]}</span><div><h2 className="font-black">{lead.firstName} {lead.lastName}</h2><p className="mt-1 text-xs text-slate-500">{lead.email} · {lead.phone || 'No phone'}</p></div></div><select value={lead.status} onChange={(e) => setStatus(lead.id, e.target.value as Lead['status'])} className="h-9 rounded-lg border border-slate-200 bg-white px-2 text-xs font-bold outline-none focus:border-cyan-400 dark:border-slate-700 dark:bg-slate-900" data-testid={`select-lead-status-${lead.id}`}><option value="new">New</option><option value="contacted">Contacted</option><option value="qualified">Qualified</option><option value="lost">Lost</option></select></div><p className="mt-5 max-w-3xl text-sm leading-6 text-slate-600 dark:text-slate-300">{lead.message}</p><div className="mt-5 flex items-center justify-between border-t border-slate-100 pt-4 dark:border-slate-800"><span className="font-mono text-[10px] text-slate-400">Preferred: {lead.preferredDate}</span><span className="font-mono text-[10px] text-slate-400">Received {new Date(lead.submittedAt).toLocaleDateString()}</span></div></div>)}</div></AdminShell>;
}

function Router() {
  return <Switch><Route path="/" component={Home} /><Route path="/services" component={ServicesPage} /><Route path="/services/:id" component={ServiceDetail} /><Route path="/technologies" component={TechnologiesPage} /><Route path="/solutions" component={SolutionsPage} /><Route path="/projects" component={ProjectsPage} /><Route path="/projects/:id" component={ProjectDetail} /><Route path="/appointment" component={Appointment} /><Route path="/admin/login" component={AdminLogin} /><Route path="/admin" component={AdminDashboard} /><Route path="/admin/services"><AdminResource kind="services" /></Route><Route path="/admin/technologies"><AdminResource kind="technologies" /></Route><Route path="/admin/solutions"><AdminResource kind="solutions" /></Route><Route path="/admin/projects"><AdminResource kind="projects" /></Route><Route path="/admin/leads" component={AdminLeads} /><Route component={NotFound} /></Switch>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedErrorBoundary><Router /></RoutedErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;